def seed_icons(apps, schema_editor):
    Esence_Items_Shop = apps.get_model('player_site_app', 'Esence_Items_Shop')
    # Odstranit staré testovací / provizorní ikonky, pokud existují
    valid_names = {name for _, name, _, _ in ICONS_CATALOG}
    Esence_Items_Shop.objects.filter(category='icons').exclude(name__in=valid_names).delete()

    for slug, name, rarity, cost in ICONS_CATALOG:
        image_rel_path = f"esence_items/icons/{slug}.svg"
        obj = Esence_Items_Shop.objects.filter(name=name, category='icons').first()
        if not obj:
            Esence_Items_Shop.objects.create(
                name=name,
                category='icons',
                rarity=rarity,
                cost=cost,
                image=image_rel_path
            )
        else:
            obj.image = image_rel_path
            obj.rarity = rarity
            obj.cost = cost
            obj.save(update_fields=['image', 'rarity', 'cost'])


def remove_seeded_icons(apps, schema_editor):
    Esence_Items_Shop = apps.get_model('player_site_app', 'Esence_Items_Shop')
    for _, name, _, _ in ICONS_CATALOG:
        Esence_Items_Shop.objects.filter(name=name, category='icons').delete()


